CREATE TABLE categories (id BIGSERIAL PRIMARY KEY,name VARCHAR(60) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX ux_categories_name_active ON categories(lower(name)) WHERE active;
CREATE TABLE products (id BIGSERIAL PRIMARY KEY,name VARCHAR(100) NOT NULL,category_id BIGINT NOT NULL REFERENCES categories(id),price_cents INTEGER NOT NULL CHECK(price_cents BETWEEN 0 AND 99999999),active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_products_category_active ON products(category_id) WHERE active;
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY,customer_name VARCHAR(80),table_label VARCHAR(20),status VARCHAR(10) NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','canceled')),total_cents BIGINT NOT NULL DEFAULT 0 CHECK(total_cents>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),closed_at TIMESTAMPTZ,CHECK((status='open')=(closed_at IS NULL)));
CREATE INDEX ix_orders_open_created ON orders(created_at) WHERE status='open'; CREATE INDEX ix_orders_status_closed ON orders(status,closed_at DESC);
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id BIGINT NOT NULL REFERENCES products(id),product_name VARCHAR(100) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 999),unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0),total_cents BIGINT NOT NULL CHECK(total_cents>=0),notes VARCHAR(200),status VARCHAR(10) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','done')),done_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((status='done')=(done_at IS NOT NULL)));
CREATE INDEX ix_order_items_order ON order_items(order_id,created_at,id);
